recipes.code:
{
  "inputs": [
    {
      "id": "marketintell-api-key",
      "type": "promptString",
      "description": "API key for the underlying MarketIntell account. Required for tool calls; optional for capability discovery.",
      "password": true
    }
  ],
  "servers": {
    "marketintell": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "mcp",
        "marketintell@0.2.1"
      ],
      "env": {
        "MARKETINTELL_API_KEY": "${input:marketintell-api-key}"
      }
    }
  }
}
